entries[105700] = { ["name"] = "Kun-Lai-Hammer", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Das besondere Braumondfestgebirgsbräu aus Binan.\"\nVerkaufspreis:" }
entries[105701] = { ["name"] = "Grünsteinbräu", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Grünsteins besonderes, von Jade durchdrungenes Waldbräu.\"\nVerkaufspreis:" }
entries[105702] = { ["name"] = "Hammerbräu", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Braumeisterin Blanches kribbelndes Jadewaldquellbräu.\"\nVerkaufspreis:" }
entries[105703] = { ["name"] = "Sturmbräugebräu", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Hergestellt in der größten und berühmtesten Brauerei des Tals der Vier Winde. Eher schwach.\"\nVerkaufspreis:" }
entries[105704] = { ["name"] = "Yan-Zhus Loderbräu", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Onkel Gao Sturmbräus seltsam gewürztes \"Bräu aller Bräus\". Hoch entzündlich.\"\nVerkaufspreis:" }
entries[105705] = { ["name"] = "Chanis Bitterbräu", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. insgesamt ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Gebraut mit einer absolut absurden Menge an Kun-Lai-Hopfen. EXTREM stark.\"\nVerkaufspreis:" }
